INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11922, 12766, 'tt0047647', NULL, 'Vera Cruz', 'Vera Cruz', 'movie', 1954, 'https://image.tmdb.org/t/p/w500/7sDTIHW0nG8CqzskwBJtmUnBwcK.jpg', 'https://image.tmdb.org/t/p/original/oftyzHLMpnpOHe5gV5Vvf0tu7o6.jpg', 'After the American Civil War, mercenaries travel to Mexico to fight in their revolution for money. The former soldier and gentleman Benjamin Trane meets the gunman and killer Joe Erin and his men, and together they are hired by the Emperor Maximillian and the Marquis Henri de Labordere to escort the Countess Marie Duvarre to the harbor of Vera Cruz.', NULL, NULL, 3.0533, 6.668, 0, 1.02, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11923, 128882, 'tt0066396', NULL, 'Shoot, Gringo... Shoot!', 'Spara, Gringo, spara', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/E8ACKmmkA0Y16Sa7tBxGblntgp.jpg', 'https://image.tmdb.org/t/p/original/l37PhaL6NqDWVmIjsH7zGn2ihwr.jpg', 'Chad Stark is offered his life and a nice ammount of dollars if he is to bring back the runaway son of mexican land-owner Gutierrez . This son, Fidel, teams up with an outlaw band lead by a former military man going by the name The Major. When Stark finds Fidel he is reintroduced to an old acquaintance which makes his job of returning the son a lot more difficult.', NULL, NULL, 1.055, 5.077, 0, 1.02, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11924, 13859, 'tt0051308', NULL, 'The Rifleman', 'The Rifleman', 'tv', 1958, 'https://image.tmdb.org/t/p/w500/tYf5Sc83chWG2nBlo5xKdpBBwlI.jpg', 'https://image.tmdb.org/t/p/original/4zZ0VjYxGERjhf5FdTuB0Y215Pi.jpg', 'The Rifleman is an American Western television program starring Chuck Connors as rancher Lucas McCain and Johnny Crawford as his son, Mark McCain. It was set in the 1880s in the town of North Fork, New Mexico Territory. The show was filmed in black-and-white, half-hour episodes. "The Rifleman" aired on ABC from September 30, 1958 to April 8, 1963 as a production of Four Star Television. It was one of the first prime time series to have a widowed parent raise a child.', NULL, NULL, 52.4529, 7.135, 0, 1.02, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11925, 10980, 'tt0050025', NULL, 'Have Gun, Will Travel', 'Have Gun, Will Travel', 'tv', 1957, 'https://image.tmdb.org/t/p/w500/6aJRq7FGs2axLOdZNJ2G4IOQtMx.jpg', 'https://image.tmdb.org/t/p/original/7z1QYCB1cu06u3oJwIupRlZ8SrX.jpg', 'Have Gun – Will Travel is an American Western television series that aired on CBS from 1957 through 1963. It was rated number three or number four in the Nielsen ratings every year of its first four seasons. It was one of the few television shows to spawn a successful radio version. The radio series debuted November 23, 1958.

The television show is presently shown on the Encore-Western channel.

Have Gun – Will Travel was created by Sam Rolfe and Herb Meadow and produced by Frank Pierson, Don Ingalls, Robert Sparks, and Julian Claman. There were 225 episodes of the TV series, 24 written by Gene Roddenberry. Other contributors included Bruce Geller, Harry Julian Fink, Don Brinkley and Irving Wallace. Andrew McLaglen directed 101 episodes and 19 were directed by series star Richard Boone.', NULL, NULL, 49.9827, 7.33, 0, 1.02, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
