INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11974, 427023, 'tt6082614', NULL, 'Tiger Girl', 'Tiger Girl', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/iGnbgXQ39qtopRZDmBnYG9gR3lJ.jpg', 'https://image.tmdb.org/t/p/original/rnDl65lrl87JgZGe8D8w6OwNYGo.jpg', 'Having failed to get into the police force, Margarete takes up training as a security guard. One night she runs into a sexually agressive ex-colleague who insists on hailing a taxi to take her home to his place. Enter Tiger: short brown hair, a tough girl and a fighter, the cab driver. Realising that the situation is far from consensual, Tiger speeds off with Margarete, leaving her companion standing in the street. It won’t be the last time she rushes to Margarete’s aid. Tiger lives in an attic flat with two men. She knows how to wield a baseball bat. Stealing a uniform from security and renaming Margarete ‘Vanilla’, she begins to steer her life in a completely different direction.', NULL, NULL, 1.0644, 5.411, 0, 9.025, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
