INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11982, 77396, 'tt0184169', NULL, 'Ultraseven', 'ウルトラセブン', 'tv', 1967, 'https://image.tmdb.org/t/p/w500/4HEtZZY4OISae6vpMCzREyzXFQi.jpg', 'https://image.tmdb.org/t/p/original/1JVWrylr0FVT7GAQifBs4IJLt5e.jpg', 'In the not-too-distant future, the Earth finds itself constantly under attack from extraterrestrial threats. The Terrestrial Defense Force establishes the Ultra Garrison, a team of six elite members who utilize high-tech vehicles and weaponry. Joining their fight is the mysterious Dan Moroboshi, secretly an alien from the Land of Light in Nebula M-78, who transforms into his true form in times of crisis, Ultraseven.', NULL, NULL, 17.8816, 7.9, 0, 11.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
