INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11984, 37786, 'tt1261945', NULL, 'Sex and the City 2', 'Sex and the City 2', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/iHSRxhZsPaVuLCivvV6WEkMVGWU.jpg', 'https://image.tmdb.org/t/p/original/gPqqEBBpSl7E4Fz8uMBqoBLxcTP.jpg', 'Carrie, Charlotte, and Miranda are all married now, but they''re still up for a little fun in the sun. When Samantha gets the chance to visit one of the most extravagant vacation destinations on the planet and offers to bring them all along, they surmise that a women-only retreat may be the perfect excuse to eschew their responsibilities and remember what life was like before they decided to settle down.', NULL, NULL, 7.7296, 6.04, 0, 9.02, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
