INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11999, 1152886, 'tt4778394', NULL, 'Hitori Kakurenbo: Hide-and-Seek', 'Hitori Kakurenbo: Hide-and-Seek', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/elnCoa3az1gagxKwZNOL6NfkTrF.jpg', NULL, 'Hitori Kakurenbo in Japanese refers to an urban legend ritual that is meant to summon a ghost or other spirit into ones home. As early as July 2007, descriptions of how to play One-Man Hide and Seek were posted on Japanese horror bulletin boards. The instructions tell the reader to fill a bathtub with stuffed animals, turn off all of the lights and chant ritualistic phrases while holding a knife. It asserted that people who had done this found that the toys had moved slightly and the television had turned on, blaring music. This is a story of a young woman playing this game, and the events that happened to her during the night. This chilling account of the supernatural, will keep the audience at the edge or their seats and have them wondering would they dare to play this game.', NULL, NULL, 0.3966, 0.0, 0, 11.03, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
