INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12008, 62761, 'tt0071282', NULL, 'The Cars That Ate Paris', 'The Cars That Ate Paris', 'movie', 1974, 'https://image.tmdb.org/t/p/w500/noP0fjvOK6kguBfG3976jS0wFbt.jpg', 'https://image.tmdb.org/t/p/original/LhNAYzoYqJssVojll2eyKLonu6.jpg', 'After surviving a car accident, a young man finds himself trapped in the isolated town of Paris, where the local economy depends on deliberately causing crashes and salvaging the wreckage. As he becomes entangled in the town’s routines, tensions between its residents and a rebellious group of youths begin to surface.', NULL, NULL, 2.2652, 5.57, 0, 1.05, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12009, 7755, 'tt1270367', NULL, 'How Not to Live Your Life', 'How Not to Live Your Life', 'tv', 2008, 'https://image.tmdb.org/t/p/w500/1R9QAs40TeF8o8uG5QbHvOAvPu0.jpg', 'https://image.tmdb.org/t/p/original/6rAfCGjuTbEU1Pm1PXoWdlPlsu6.jpg', 'Sitcom about 20-something Don, a man with bad luck and even worse instincts. Don''s overactive imagination is always in full flow in the form of quick-fire fantasy sequences as he imagines what he would really like to say.', NULL, NULL, 4.4564, 7.6, 0, 1.02, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12010, 1459, 'tt0450357', NULL, 'Wonder Showzen', 'Wonder Showzen', 'tv', 2005, 'https://image.tmdb.org/t/p/w500/vEubk3DuGLNdlLi3xmlSOMwdPrm.jpg', 'https://image.tmdb.org/t/p/original/uARlYC9mu0EQx3VQODDMvsn1vY9.jpg', 'Wonder Showzen is an American sketch comedy television series that aired between 2005 and 2006 on MTV2. It was created by John Lee and Vernon Chatman of PFFR. The show is rated TV-MA.

The show''s format is that of educational PBS children''s television shows such as Sesame Street and The Electric Company, parodying the format with adult-oriented content. In addition to general controversial comedy, it satirizes politics, religion, war, sex, and culture with black comedy.

Every episode begins with a disclaimer, accompanied by the sound of someone screaming "Don''t eat my baby!", which reads:

"Wonder Showzen contains offensive, despicable content that is too controversial and too awesome for actual children. The stark, ugly and profound truths Wonder Showzen exposes may be soul-crushing to the weak of spirit. If you allow a child to watch this show, you are a bad parent or guardian."', NULL, NULL, 6.1831, 7.2, 0, 1.0, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
