INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12062, 20704, 'tt0102517', NULL, 'Necessary Roughness', 'Necessary Roughness', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/lZsD4izDMKbV1KTRUQ5UVWZrnLJ.jpg', 'https://image.tmdb.org/t/p/original/vKADL4Ux4liQqnNJEv2RT66gdzZ.jpg', 'When the Texas State University Fightin'' Armadillos football team is disqualified for cheating and poor grades, the University is forced to pick from a team that actually goes to school. Will they even win a single game?', NULL, NULL, 2.8118, 5.482, 0, 7.51, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12063, 892153, 'tt15831226', NULL, 'Tom and Jerry Cowboy Up!', 'Tom and Jerry Cowboy Up!', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/muIaHotSaSUQr0KZCIJOYQEe7y2.jpg', 'https://image.tmdb.org/t/p/original/q1NXVYTqSStNQsnKrCvtU6NPzEk.jpg', 'This time, the rivals team up to help a cowgirl and her brother save their homestead from a greedy land-grabber, and they’re going to need some help! Jerry’s three precocious nephews are all ready for action, and Tom is rounding up a posse of prairie dogs. But can a ragtag band of varmints defeat a deceitful desperado determined to deceive a damsel in distress? No matter what happens with Tom and Jerry in the saddle, it’ll be a rootin’ tootin’ good time!', NULL, NULL, 3.4853, 6.878, 0, 8.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12064, 31967, 'tt1401113', NULL, 'Dante''s Inferno: An Animated Epic', 'Dante''s Inferno: An Animated Epic', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/nAEGEYTjbli3JoFgyrLn3blxDqi.jpg', 'https://image.tmdb.org/t/p/original/abXyMAzeL3aBoAuVcqIChuwq3DR.jpg', 'Dante journeys through the nine circles of Hell -- limbo, lust, gluttony, greed, anger, heresy, violence, fraud and treachery -- in search of his true love, Beatrice. An animated version of the video game of the same name.', NULL, NULL, 3.1628, 6.974, 0, 10.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12065, 13334, 'tt0416316', NULL, 'Wolfhound of the Grey Dog Clan', 'Волкодав из рода Серых Псов', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/7uWSweoe5ykaxpEmXvzaEOHQFl7.jpg', 'https://image.tmdb.org/t/p/original/oTOUJCvds5zFcMcgTpqlOmbq30r.jpg', 'He was doomed to die, but managed to survive, and now his mission is to revenge for the annihilation of his tribe. He is the great warrior who calls himself Volkodav, and is the last man from the tribe of Serie Psi (Grey Hounds). After escaping certain death, Volkodaw — accompanied by Neletuchaya Mysh — is on a mission to kill Ludoed who is responsible to what happened to Serie Psi.', NULL, NULL, 1.8084, 5.473, 0, 8.51, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12066, 79433, 'tt1629374', NULL, 'Ronal the Barbarian', 'Ronal Barbaren', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/vT8m9Ji4mrUExpuIX0LGjMPHEHX.jpg', 'https://image.tmdb.org/t/p/original/f3xcA9b0Hl02PNLu9DRPe6S1A7.jpg', 'Ronal is a young barbarian with low self-esteem, the polar opposite of all the muscular barbarians in his village. He''s a real wuss. However, as fate would have it, responsibility for the tribe''s survival falls on Ronal''s scrawny shoulders, when the evil Lord Volcazar raids the village and abducts every living barbarian with the exception of Ronal, who is forced to go on a perilous quest to save his enslaved clan and thwart Volcazar’s plot to rule the world.', NULL, NULL, 3.375, 6.094, 0, 8.51, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12067, 38219, 'tt0084935', NULL, 'Yor: The Hunter from the Future', 'Il mondo di Yor', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/8cMkOOHlJaeQKgGPakxc6sEHHKJ.jpg', 'https://image.tmdb.org/t/p/original/wS8BqmSiiyLPgz5oybAybDHeXTy.jpg', 'Yor is an extremely blond prehistoric warrior who comes to question his origins, particularly with regard to a mysterious medallion he wears. When he learns of a desert goddess who supposedly wears the same medallion, Yor decides that he must find her and learn his true identity. Along the way, he encounters ape-men, dinosaurs, and a strange futuristic society.', NULL, NULL, 1.6289, 4.233, 0, 9.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
