INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12069, 864959, 'tt15289240', NULL, 'The Curse of Bridge Hollow', 'The Curse of Bridge Hollow', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/t6P9l6tcVnWLS1ADUAfkUCGQhm0.jpg', 'https://image.tmdb.org/t/p/original/pZv3qb5wK3h0kOUL2HOloYioAT9.jpg', 'A Halloween-hating dad reluctantly teams up with his teenage daughter when an evil spirit wreaks havoc by making their town''s decorations come to life.', NULL, NULL, 4.1976, 6.501, 0, 1.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12070, 70587, 'tt1792131', NULL, 'Spooky Buddies', 'Spooky Buddies', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/cC6NleO3bn2FgFpkJx1RQvjccWL.jpg', 'https://image.tmdb.org/t/p/original/d79CoC9Hq3ZKuQr9v2SFMLtWiZV.jpg', 'The nefarious Warwick the Warlock has returned from his astral imprisonment, and plans to make the final sacrifice for ultimate power - all he needs is the soul of a pure heart. The Buddies, alongside their new spectral friend Pip, race against the clock to defeat the sorcerer, who has enlisted the Halloween Hound to do his dirty work under the cover of the neighborhood festivities.', NULL, NULL, 3.0098, 6.0, 0, 1.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
