INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12073, 25438, 'tt0092112', NULL, 'Trick or Treat', 'Trick or Treat', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/ycCrGbfuOEcKSCwxQeKA1VEPs7O.jpg', 'https://image.tmdb.org/t/p/original/7z70u9gAVTeUfSIxf2jbiDZTry1.jpg', 'Eddie Weinbauer, a metalhead teen who is bullied at school, looks to his heavy metal superstar idol, Sammi Curr, for guidance. When Curr is killed in a hotel fire, Eddie becomes the recipient of the only copy of his unreleased album, which, when played backwards, brings the rocker back to life. As Halloween approaches, Eddie begins to realize that this isn''t only rock ''n roll...It''s life and death.', NULL, NULL, 3.4791, 6.088, 0, 2.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12074, 95114, 'tt0093135', NULL, 'Hack-O-Lantern', 'Hack-O-Lantern', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/n6ImVjGNGzDltAafgTGYx7NmwNj.jpg', 'https://image.tmdb.org/t/p/original/hssT0rlZjZFn5kRHgs8eNwFiy1t.jpg', 'When Tommy was a boy, he saw his grandpa, the leader of a vicious satanic cult, murder his father in a brutal ritual on Halloween night. Now he is 18, and grandpa is ready to indoctrinate him into the ways of the black arts.', NULL, NULL, 1.3813, 4.95, 0, 1.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
