INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12076, 149590, 'tt1991059', NULL, 'Halloween Party', 'Halloween Party', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/z7oIsxIWwY03MsmeGD2qF0LZprq.jpg', NULL, 'Ben and Julie''s annual Halloween Party is about to go off the Richter scale, when their single, high maintenance girlfriend drags in a homeless guy, thinking he''s a party goer, because SHE needs an escort. Not only has she dated everyone there; unbeknownst to her, Ben has invited her lame ex-boyfriend in hopes of reuniting them. As she spends the night avoiding her ex, and the other undesirable guys in attendance, she interacts with a colorful assortment of party peeps. Between disappearing fortune tellers and over crowded jacuzzis, she questions if real love is even possible. The irony; the only person she''s the least bit attracted to, is the homeless man!', NULL, NULL, 1.6068, 5.8, 0, 1.01, '2026-08-25 01:38:26', '2026-08-25 01:38:26');
