UPDATE "recommendations" SET "tmdb_id"=11905, "imdb_id"='tt0087075', "igdb_id"=NULL, "title"='The Company of Wolves', "original_title"='The Company of Wolves', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/2g2YPws1MiEWTodUE8u3qOf78XS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8LMKwSUdHxU8AGPVY7BV4wS5TeQ.jpg', "overview"='An adaptation of Angela Carter''s fairy tales. Young Rosaleen dreams of a village in the dark woods, where Granny tells her cautionary tales in which innocent maidens are tempted by wolves who are hairy on the inside. As Rosaleen grows into womanhood, will the wolves come for her too?', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6119, "vote_average"=6.3, "is_ambiguous"=0, "evidence_score"=3.17217857142857155e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=20;
UPDATE "recommendations" SET "tmdb_id"=179111, "imdb_id"='tt2375574', "igdb_id"=NULL, "title"='A Field in England', "original_title"='A Field in England', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/dKhMJr8yoHVyvxyUiAeIn2hKVdL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/euBvKWkvYD38O7dMMvw3GvrkZoa.jpg', "overview"='During the Civil War in 17th-Century England, a small group of deserters flee from a raging battle through an overgrown field. They are captured by an alchemist, who forces the group to aid him in his search to find a hidden treasure that he believes is buried in the field. Crossing a vast mushroom circle, which provides their first meal, the group quickly descend into a chaos of arguments, fighting and paranoia, and, as it becomes clear that the treasure might be something other than gold, they slowly become victim to the terrifying energies trapped inside the field.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.193, "vote_average"=6.212, "is_ambiguous"=0, "evidence_score"=2.10611111111111135e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=21;
UPDATE "recommendations" SET "tmdb_id"=13597, "imdb_id"='tt0091369', "igdb_id"=NULL, "title"='Labyrinth', "original_title"='Labyrinth', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mGkleIuPO2flRyvP8yBcUykSQsp.jpg', "overview"='Frustrated with babysitting on yet another weekend night, Sarah, a teenager with an active imagination, summons the Goblins to take her baby stepbrother away. When little Toby actually disappears, Sarah must follow him into a fantastical world to rescue him from the Goblin King. Guarding his castle is the labyrinth itself, a twisted maze of deception, populated with outrageous characters and unknown dangers.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6038, "vote_average"=7.289, "is_ambiguous"=0, "evidence_score"=64.655, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=23;
UPDATE "recommendations" SET "tmdb_id"=2637, "imdb_id"='tt0265349', "igdb_id"=NULL, "title"='The Mothman Prophecies', "original_title"='The Mothman Prophecies', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/z2PiOTyjbCOnMHY2QJdq3I4jU44.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/zQM01PhOwJY9ePnWPQ8L0YeKf8c.jpg', "overview"='Reporter John Klein is plunged into a world of impossible terror when fate draws him to the sleepy West Virginia town of Point Pleasant, whose residents are being visited by a great winged shape that sows hideous nightmares and fevered visions.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.248, "vote_average"=6.223, "is_ambiguous"=0, "evidence_score"=4.73365116279069724e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=24;
UPDATE "recommendations" SET "tmdb_id"=546554, "imdb_id"='tt8946378', "igdb_id"=NULL, "title"='Knives Out', "original_title"='Knives Out', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4HWAQu28e2yaWrtupFPGFkdNU7V.jpg', "overview"='When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.1335, "vote_average"=7.84, "is_ambiguous"=0, "evidence_score"=23.928, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=25;
