UPDATE "recommendations" SET "tmdb_id"=8909, "imdb_id"='tt0493464', "igdb_id"=NULL, "title"='Wanted', "original_title"='Wanted', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/njy7Pz7ZHZceO7lNfGIHKphY8Hd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vjwuT8EzWY96W6nrJKZNI2WJU87.jpg', "overview"='Doormat Wesley Gibson is an office worker whose life is going nowhere. He meets an attractive woman named Fox and discovers that his recently murdered father - whom Wesley never knew - belonged to the Fraternity, a secret society of assassins which takes its orders from Fate itself. Fox and Sloan, the Fraternity''s leader, teach Wesley, through intense training, to tap into dormant powers and hone his innate killing skills. Though he enjoys his newfound abilities, he begins to suspect that there is more to the Fraternity than meets the eye.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.8851, "vote_average"=6.53, "is_ambiguous"=0, "evidence_score"=1.80238461538461542e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=648;
