UPDATE "recommendations" SET "tmdb_id"=31414, "imdb_id"='tt0111341', "igdb_id"=NULL, "title"='Satantango', "original_title"='Sátántangó', "media_type"='movie', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/y38z0v4HJ12MHiKddLEoFlvPiBt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5a4Gmk2HNeefI4Rmwdmbyoy79oy.jpg', "overview"='Inhabitants of a small village in Hungary deal with the effects of the fall of Communism. The town''s source of revenue, a factory, has closed, and the locals, who include a doctor and three couples, await a cash payment offered in the wake of the shuttering. Irimias, a villager thought to be dead, returns and, unbeknownst to the locals, is a police informant. In a scheme, he persuades the villagers to form a commune with him.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.9537, "vote_average"=8.037, "is_ambiguous"=0, "evidence_score"=16.421, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=1132;
