UPDATE "recommendations" SET "tmdb_id"=9473, "imdb_id"='tt0158983', "igdb_id"=NULL, "title"='South Park: Bigger, Longer & Uncut', "original_title"='South Park: Bigger, Longer & Uncut', "media_type"='movie', "release_year"=1999, "poster_url"='https://image.tmdb.org/t/p/w500/tS0PedvA2mFO9VCHYwQpaU1K36U.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2q3B90h2hZ6xJTvna9CIFDNaIr4.jpg', "overview"='In this feature film based on the hit animated series, the third graders of South Park sneak into an R-rated film by ultra-vulgar Canadian television personalities Terrance and Phillip, and emerge with expanded vocabularies that leave their parents and teachers scandalized. When outraged Americans try to censor the film, the controversy spirals into a call to wage war on Canada and Terrance and Phillip end up on death row, with the kids their only hope of rescue.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6046, "vote_average"=7.284, "is_ambiguous"=0, "evidence_score"=11.27, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=2067;
