UPDATE "recommendations" SET "tmdb_id"=132344, "imdb_id"='tt2209418', "igdb_id"=NULL, "title"='Before Midnight', "original_title"='Before Midnight', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/qbGKJmNUroDz75kh5Oafoall89e.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/crdW75sDNYM0ddjFyrcg6V59qdP.jpg', "overview"='It has been nine years since we last met Jesse and Celine, the French-American couple who once met on a train in Vienna. They now live in Paris with twin daughters but have spent a summer in Greece at the invitation of an author colleague of Jesse''s. When the vacation is over and Jesse must send his teenage son off to the States, he begins to question his life decisions, and his relationship with Celine is at risk.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6858, "vote_average"=7.491, "is_ambiguous"=0, "evidence_score"=14.11, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-25 01:38:26' WHERE "id"=2250;
