UPDATE "recommendations" SET "tmdb_id"=9702, "imdb_id"='tt0106469', "igdb_id"=NULL, "title"='Bound by Honor', "original_title"='Bound by Honor', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/xD0xcDkII1t5j3d6c68t1GYzP6S.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9xjUZjuYyehv2qnqMH0oR9nSTft.jpg', "overview"='Based on the true life experiences of poet Jimmy Santiago Baca, the film focuses on half-brothers Paco and Cruz, and their bi-racial cousin Miklo. It opens in 1972, as the three are members of an East L.A. gang known as the "Vatos Locos", and the story focuses on how a violent crime and the influence of narcotics alter their lives. Miklo is incarcerated and sent to San Quentin, where he makes a "home" for himself. Cruz becomes an exceptional artist, but a heroin addiction overcomes him with tragic results. Paco becomes a cop and an enemy to his "carnal", Miklo.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.704, "vote_average"=8.204, "is_ambiguous"=0, "evidence_score"=1.55183333333333344e+01, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-25 01:38:26' WHERE "id"=4336;
