UPDATE "recommendations" SET "tmdb_id"=404245, "imdb_id"='tt4528454', "igdb_id"=NULL, "title"='Starfish', "original_title"='Starfish', "media_type"='movie', "release_year"=2016, "poster_url"='https://image.tmdb.org/t/p/w500/ysjAdklkfNlQ7t6CCf3QwgU5oU6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uh3Zb9M1nVwf1nXbu8Dz8NO08vE.jpg', "overview"='Based on the real story of Tom and Nicola Ray from Rutland. Their perfect life is totally ruined in a single moment after Tom had developed sepsis. While her husband was in coma, Nicola gave birth to their second child on the other side of the same hospital. Within a matter of days, sepsis would rob Tom of both his arms and legs, and left his face severely disfigured. As an ordinary man, Tom never put himself at risk — he just woke up two months later in a nightmare, a face-off quadruple amputee... This incredible story of survival shows what can be overcome when love is unconditional.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.8274, "vote_average"=6.568, "is_ambiguous"=0, "evidence_score"=6.01500000000000056e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-25 01:38:26' WHERE "id"=6195;
