UPDATE "recommendations" SET "tmdb_id"=25199, "imdb_id"='tt0098453', "igdb_id"=NULL, "title"='Teen Witch', "original_title"='Teen Witch', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/8UNA7PZ9gpoIgELB13bKCwOuICp.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vRfo7aDU9k10G1FUSixOCPbcBmr.jpg', "overview"='Louise is not very popular at her highschool. Then she learns that she''s descended from the witches of Salem and has inherited their powers. At first she uses them to get back at the girls and teachers who teased her and to win the heart of the handsome footballer''s captain. But soon she has doubts if it''s right to ''cheat'' her way to popularity.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.0137, "vote_average"=6.036, "is_ambiguous"=0, "evidence_score"=12.794, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-25 01:38:26' WHERE "id"=6266;
UPDATE "recommendations" SET "tmdb_id"=522039, "imdb_id"='tt4353250', "igdb_id"=NULL, "title"='The Last Black Man in San Francisco', "original_title"='The Last Black Man in San Francisco', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/ow9zjibNrz5TYVZ6cqwmvCR1YX1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/n0FzDpOvVhkj3uN7WHXXnAXOKFi.jpg', "overview"='Jimmie Fails dreams of reclaiming the Victorian home his grandfather built in the heart of San Francisco. Joined on his quest by his best friend Mont, Jimmie searches for belonging in a rapidly changing city that seems to have left them behind.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.7538, "vote_average"=6.982, "is_ambiguous"=0, "evidence_score"=6.26, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-25 01:38:26' WHERE "id"=6279;
UPDATE "recommendations" SET "tmdb_id"=294254, "imdb_id"='tt4046784', "igdb_id"=NULL, "title"='Maze Runner: The Scorch Trials', "original_title"='Maze Runner: The Scorch Trials', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/mYw7ZyejqSCPFlrT2jHZOESZDU3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4mcOCiR06dqQ5eoEJcG3zvonjOa.jpg', "overview"='Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.34, "vote_average"=6.731, "is_ambiguous"=0, "evidence_score"=6.01500000000000056e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-25 01:38:26' WHERE "id"=6324;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=999, "title"='Oddworld: Abe''s Oddysee', "original_title"='Oddworld: Abe''s Oddysee', "media_type"='game', "release_year"=1997, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co89fk.jpg', "backdrop_url"=NULL, "overview"='Oddworld: Abe''s Oddysee is the first game set in the fictional Oddworld universe. It is a platformer with puzzle-solving elements, focusing on the portrayal of a weak, underpowered character in a grim and hostile world, who has to rely on his cunning to outwit enemies and overcome hazards. The game has pre-rendered background graphics and uses CG movies of similar style to advance the story between the levels.

The main character Abe is almost completely helpless: he cannot use weapons and is usually instantly killed by his brutal enemies if he confronts them directly. For this reason, most of the game involves careful exploration, timed movement, sneaking, and outsmarting the foes through various means: throwing stones to confuse them, luring them into traps, etc. Abe can run, jump, climb, tiptoe, crouch, and roll; in most areas these actions are essential to his survival. A few stages involve Abe riding a large animal known as Elum.

Abe''s only special power is chanting, which he can use to stun certain enemies for a while or possess them. When Abe possess an enemy he gains his abilities: for example, possessing the body or a ferocious Slig allows the player to shoot from his machine gun, communicate with other creatures of his kind, and even commit suicide, clearing the way for Abe.', "external_url"='https://www.igdb.com/games/oddworld-abe-s-oddysee', "platforms"='["OnLive Game System", "PlayStation 3", "PC (Microsoft Windows)", "DOS", "PlayStation", "PlayStation Portable"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=9.17666666666666586e+00, "created_at"='2026-07-31 03:33:23', "updated_at"='2026-08-25 01:38:26' WHERE "id"=6336;
