UPDATE "recommendations" SET "tmdb_id"=442062, "imdb_id"='tt5664636', "igdb_id"=NULL, "title"='Goosebumps 2: Haunted Halloween', "original_title"='Goosebumps 2: Haunted Halloween', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/t2wy38iiMpB8WsgJi3lYeDnGh2H.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/h5BvesqaxL7V3vl1CmaR8waGyiM.jpg', "overview"='Be careful what you wish for. With their after school junk business, best friends Sonny and Sam hope to find treasure in other people’s trash. But when cleaning out the old Stine house, they open a locked book that frees a supernatural nightmare – Slappy! Now, with the help of Sonny’s sister Sarah, they’re in a race against time to get the sinister dummy and all the creatures he’s brought to life back into the pages before he unleashes total pandemonium!', "external_url"=NULL, "platforms"=NULL, "popularity"=7.0902, "vote_average"=6.091, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-08-06 03:21:21', "updated_at"='2026-08-25 01:38:26' WHERE "id"=7825;
