UPDATE "recommendations" SET "tmdb_id"=96580, "imdb_id"='tt8690918', "igdb_id"=NULL, "title"='Resident Alien', "original_title"='Resident Alien', "media_type"='tv', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/5van3ktOTqWr5lcixh5aR8NlqqW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aCbOj4wc6vQUUVNKppssj2PYUy0.jpg', "overview"='Crash-landed alien Harry takes on the identity of a small-town Colorado doctor. Arriving with a secret mission, he starts off living a simple life…but things get a bit rocky when he’s roped into solving a local murder and realizes he needs to assimilate into his new world. As he does, he begins to wrestle with the moral dilemma of his mission and asking the big life questions like: “Are human beings worth saving?” and “Why do they fold their pizza before eating it?”', "external_url"=NULL, "platforms"=NULL, "popularity"=36.7893, "vote_average"=7.788, "is_ambiguous"=0, "evidence_score"=6.025, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-25 01:38:26' WHERE "id"=7960;
