UPDATE "recommendations" SET "tmdb_id"=8872, "imdb_id"='tt0105793', "igdb_id"=NULL, "title"='Wayne''s World', "original_title"='Wayne''s World', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/fHwZnFNWR7PaS9t5EBwTvGPeoYQ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lAvf5zzyOgTZmpRBRJFa7IVVqCK.jpg', "overview"='The adventures of two amiably aimless metal-head friends, Wayne and Garth. From Wayne''s basement, the pair broadcast a talk-show called "Wayne''s World" on local public access television. The show comes to the attention of a sleazy network executive who wants to produce a big-budget version of "Wayne''s World"—and he also wants Wayne''s girlfriend, a rock singer named Cassandra. Wayne and Garth have to battle the executive not only to save their show, but also Cassandra.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.1028, "vote_average"=6.684, "is_ambiguous"=0, "evidence_score"=1.16233333333333348e+01, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-25 01:38:26' WHERE "id"=8016;
