UPDATE "recommendations" SET "tmdb_id"=1639, "imdb_id"='tt0120179', "igdb_id"=NULL, "title"='Speed 2: Cruise Control', "original_title"='Speed 2: Cruise Control', "media_type"='movie', "release_year"=1997, "poster_url"='https://image.tmdb.org/t/p/w500/gnK1ocpwUTj24zAktzomOJsD2bu.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/wmwEjQpqNXEIadsQoqWUS1pVVBi.jpg', "overview"='A disgruntled former employee hijacks the Seabourn Legend cruise liner. Set on a fixed course, without any means of communication and at the mercy of the hijacker, it''s up to the one cop on vacation, and his soon to be fiancé (hopefully) Annie, to regain control of it before it kills the passengers and causes an environmental disaster. Insurmountable and daunting tasks await them on their  perilous journey throughout the ship trying to fend off the hijacker and save the passengers.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.8935, "vote_average"=4.6, "is_ambiguous"=0, "evidence_score"=5.51, "created_at"='2026-08-09 02:29:31', "updated_at"='2026-08-25 01:38:26' WHERE "id"=8731;
