UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=17, "title"='Fallout Tactics: Brotherhood of Steel', "original_title"='Fallout Tactics: Brotherhood of Steel', "media_type"='game', "release_year"=2001, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co1ybr.jpg', "backdrop_url"=NULL, "overview"='This is a Tactical Squad-Based Combat comes to the Fallout Universe. You are the wretched refuse. You may be born from dirt, but we will forge you into steel. You will learn to bend; if not you, will you break. In these dark times, the Brotherhood - your Brotherhood - is all that stands between the rekindled flame of civilization and the howling, radiated wasteland.

Your weapons will become more than your tools, they will become your friends. You will use your skills to inspire the lowly and protect the weak... whether they like it or not. Your squadmates will be more dear to you than your kin and for those that survive there will be honor, respect and the spoils of war.', "external_url"='https://www.igdb.com/games/fallout-tactics-brotherhood-of-steel', "platforms"='["PC (Microsoft Windows)", "Mac"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=1.32016666666666679e+01, "created_at"='2026-08-10 02:34:01', "updated_at"='2026-08-25 01:38:26' WHERE "id"=8941;
