UPDATE "recommendations" SET "tmdb_id"=36040, "imdb_id"='tt0067959', "igdb_id"=NULL, "title"='Walkabout', "original_title"='Walkabout', "media_type"='movie', "release_year"=1971, "poster_url"='https://image.tmdb.org/t/p/w500/24vooYt5StgtgcQObVr1GHuM5gy.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uA5GfPzRU1vRVY7pDfqXQmjRTPI.jpg', "overview"='Under the pretense of having a picnic, a geologist takes his teenage daughter and 6-year-old son into the Australian outback and attempts to shoot them. When he fails, he turns the gun on himself, and the two city-bred children must contend with harsh wilderness alone. They are saved by a chance encounter with an Aboriginal boy who shows them how to survive, and in the process underscores the disharmony between nature and modern life.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7639, "vote_average"=7.299, "is_ambiguous"=0, "evidence_score"=7.68333333333333268e+00, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-25 01:38:26' WHERE "id"=10307;
