UPDATE "recommendations" SET "tmdb_id"=257445, "imdb_id"='tt1051904', "igdb_id"=NULL, "title"='Goosebumps', "original_title"='Goosebumps', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/aeZT9pqEgrmXOGdESFkAuVjX6kw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6mPe4rBHzDMal2oL6hVgOBkaHz9.jpg', "overview"='After moving to a small town, Zach Cooper finds a silver lining when he meets next door neighbor Hannah, the daughter of bestselling Goosebumps series author R.L. Stine. When Zach unintentionally unleashes real monsters from their manuscripts and they begin to terrorize the town, it’s suddenly up to Stine, Zach and Hannah to get all of them back in the books where they belong.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.7381, "vote_average"=6.313, "is_ambiguous"=0, "evidence_score"=6.788, "created_at"='2026-08-21 01:43:43', "updated_at"='2026-08-25 01:38:26' WHERE "id"=11039;
UPDATE "recommendations" SET "tmdb_id"=11133, "imdb_id"='tt0091778', "igdb_id"=NULL, "title"='Poltergeist II: The Other Side', "original_title"='Poltergeist II: The Other Side', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/tVQPv69XWIgzF5n1MRrTuhPyNr5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qTR9c6R2p4sgax4D2npccHrv4Ze.jpg', "overview"='The Freeling family move in with Diane''s mother in an effort to escape the trauma and aftermath of Carol Anne''s abduction by the Beast. But the Beast is not to be put off so easily and appears in a ghostly apparition as the Reverend Kane, a religious zealot responsible for the deaths of his many followers. His goal is simple - he wants the angelic Carol Anne.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.96, "vote_average"=5.999, "is_ambiguous"=0, "evidence_score"=7.01333333333333275e+00, "created_at"='2026-08-21 01:43:43', "updated_at"='2026-08-25 01:38:26' WHERE "id"=11095;
UPDATE "recommendations" SET "tmdb_id"=294272, "imdb_id"='tt2788732', "igdb_id"=NULL, "title"='Pete''s Dragon', "original_title"='Pete''s Dragon', "media_type"='movie', "release_year"=2016, "poster_url"='https://image.tmdb.org/t/p/w500/A9x4Ogk8KUXTfU649NS6lS9TCmu.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ct9S0m2U2RTCFAVnq3y0nF0Tgb2.jpg', "overview"='For years, old wood carver Mr. Meacham has delighted local children with his tales of the fierce dragon that resides deep in the woods of the Pacific Northwest. To his daughter, Grace, who works as a forest ranger, these stories are little more than tall tales... until she meets Pete, a mysterious 10-year-old with no family and no home who claims to live in the woods with a giant, green dragon named Elliott. And from Pete''s descriptions, Elliott seems remarkably similar to the dragon from Mr. Meacham''s stories. With the help of Natalie, an 11-year-old girl whose father Jack owns the local lumber mill, Grace sets out to determine where Pete came from, where he belongs, and the truth about this dragon.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.0877, "vote_average"=6.391, "is_ambiguous"=0, "evidence_score"=5.51500000000000056e+00, "created_at"='2026-08-22 01:37:44', "updated_at"='2026-08-25 01:38:26' WHERE "id"=11243;
UPDATE "recommendations" SET "tmdb_id"=7857, "imdb_id"='tt0071129', "igdb_id"=NULL, "title"='Amarcord', "original_title"='Amarcord', "media_type"='movie', "release_year"=1973, "poster_url"='https://image.tmdb.org/t/p/w500/kS7i093sQpkLTawUEdgf4HVOHSc.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/iFQzlUmO5QmMPcSHHDdfd522x33.jpg', "overview"='In an Italian seaside town, young Titta gets into trouble with his friends and watches various local eccentrics as they engage in often absurd behavior. Frequently clashing with his stern father and defended by his doting mother, Titta witnesses the actions of a wide range of characters, from his extended family to Fascist loyalists to sensual women, with certain moments shifting into fantastical scenarios.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.5166, "vote_average"=7.872, "is_ambiguous"=0, "evidence_score"=1.16800000000000014e+01, "created_at"='2026-08-22 01:37:44', "updated_at"='2026-08-25 01:38:26' WHERE "id"=11256;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=2853, "title"='Braid', "original_title"='Braid', "media_type"='game', "release_year"=2008, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co25ni.jpg', "backdrop_url"=NULL, "overview"='Braid is a puzzle-platformer, drawn in a painterly style, where you can manipulate the flow of time in strange and unusual ways. From a house in the city, journey to a series of worlds and solve puzzles to rescue an abducted princess. In each world, you have a different power to affect the way time behaves, and it is time''s strangeness that creates the puzzles. The time behaviors include: the ability to rewind, objects that are immune to being rewound, time that is tied to space, parallel realities, time dilation, and perhaps more.

Braid treats your time and attention as precious; there is no filler in this game. Every puzzle shows you something new and interesting about the game world.', "external_url"='https://www.igdb.com/games/braid', "platforms"='["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=7.26, "created_at"='2026-08-22 01:37:44', "updated_at"='2026-08-25 01:38:26' WHERE "id"=11321;
